7	export type EnvironmentSanitizationConfig = {
8	  allowedEnvironmentVariables: string[];
9	  blockedEnvironmentVariables: string[];
10	  enableEnvironmentVariableRedaction: boolean;
11	};
12	
13	export function sanitizeEnvironment(
14	  processEnv: NodeJS.ProcessEnv,
15	  config: EnvironmentSanitizationConfig,
16	): NodeJS.ProcessEnv {
17	  const isStrictSanitization =
18	    !!processEnv['GITHUB_SHA'] || processEnv['SURFACE'] === 'Github';
19	
20	  if (!config.enableEnvironmentVariableRedaction && !isStrictSanitization) {
21	    return { ...processEnv };
22	  }
23	
24	  const results: NodeJS.ProcessEnv = {};
25	
26	  const allowedSet = new Set(
27	    (config.allowedEnvironmentVariables || []).map((k) => k.toUpperCase()),
28	  );
29	  const blockedSet = new Set(
30	    (config.blockedEnvironmentVariables || []).map((k) => k.toUpperCase()),
31	  );
32	
33	  for (const key in processEnv) {
34	    const value = processEnv[key];
35	
36	    if (
37	      !shouldRedactEnvironmentVariable(
38	        key,
39	        value,
40	        allowedSet,
41	        blockedSet,
42	        isStrictSanitization,
43	      )
44	    ) {
45	      results[key] = value;
46	    }
47	  }
48	
49	  return results;
50	}
51	
52	export const ALWAYS_ALLOWED_ENVIRONMENT_VARIABLES: ReadonlySet<string> =
53	  new Set([
54	    // Cross-platform
55	    'PATH',
56	    // Windows specific
57	    'SYSTEMROOT',
58	    'COMSPEC',
59	    'PATHEXT',
60	    'WINDIR',
61	    'TEMP',
62	    'TMP',
63	    'USERPROFILE',
64	    'SYSTEMDRIVE',
65	    // Unix/Linux/macOS specific
66	    'HOME',
67	    'LANG',
68	    'SHELL',
69	    'TMPDIR',
70	    'USER',
71	    'LOGNAME',
72	    // Terminal capability variables (needed by editors like vim/emacs and
73	    // interactive commands like top)
74	    'TERM',
75	    'COLORTERM',
76	    // GitHub Action-related variables
77	    'ADDITIONAL_CONTEXT',
78	    'AVAILABLE_LABELS',
79	    'BRANCH_NAME',
80	    'DESCRIPTION',
81	    'EVENT_NAME',
82	    'GITHUB_ENV',
83	    'IS_PULL_REQUEST',
84	    'ISSUES_TO_TRIAGE',
85	    'ISSUE_BODY',
86	    'ISSUE_NUMBER',
87	    'ISSUE_TITLE',
88	    'PULL_REQUEST_NUMBER',
89	    'REPOSITORY',
90	    'TITLE',
91	    'TRIGGERING_ACTOR',
92	  ]);
93	
94	export const NEVER_ALLOWED_ENVIRONMENT_VARIABLES: ReadonlySet<string> = new Set(
95	  [
96	    'CLIENT_ID',
97	    'DB_URI',
98	    'CONNECTION_STRING',
99	    'AWS_DEFAULT_REGION',
100	    'AZURE_CLIENT_ID',
101	    'AZURE_TENANT_ID',
102	    'SLACK_WEBHOOK_URL',
103	    'TWILIO_ACCOUNT_SID',
104	    'DATABASE_URL',
105	    'GOOGLE_CLOUD_PROJECT',
106	    'GOOGLE_CLOUD_ACCOUNT',
107	    'FIREBASE_PROJECT_ID',
108	  ],
109	);
110	
111	export const NEVER_ALLOWED_NAME_PATTERNS = [
112	  /TOKEN/i,
113	  /SECRET/i,
114	  /PASSWORD/i,
115	  /PASSWD/i,
116	  /KEY/i,
117	  /AUTH/i,
118	  /CREDENTIAL/i,
119	  /CREDS/i,
120	  /PRIVATE/i,
121	  /CERT/i,
122	] as const;
123	
124	export const NEVER_ALLOWED_VALUE_PATTERNS = [
125	  /-----BEGIN (RSA|OPENSSH|EC|PGP) PRIVATE KEY-----/i,
126	  /-----BEGIN CERTIFICATE-----/i,
127	  // Credentials in URL
128	  /(https?|ftp|smtp):\/\/[^:\s]{1,1024}:[^@\s]{1,1024}@/i,
129	  // GitHub tokens (classic, fine-grained, OAuth, etc.)
130	  /(ghp|gho|ghu|ghs|ghr|github_pat)_[a-zA-Z0-9_]{36,}/i,
131	  // Google API keys
132	  /AIzaSy[a-zA-Z0-9_\\-]{33}/i,
133	  // Amazon AWS Access Key ID
134	  /AKIA[A-Z0-9]{16}/i,
135	  // Generic OAuth/JWT tokens
136	  /eyJ[a-zA-Z0-9_-]{0,10240}\.[a-zA-Z0-9_-]{0,10240}\.[a-zA-Z0-9_-]{0,10240}/i,
137	  // Stripe API keys
138	  /(s|r)k_(live|test)_[0-9a-zA-Z]{24}/i,
139	  // Slack tokens (bot, user, etc.)
140	  /xox[abpr]-[a-zA-Z0-9-]+/i,
141	] as const;
142	
143	function shouldRedactEnvironmentVariable(
144	  key: string,
145	  value: string | undefined,
146	  allowedSet?: Set<string>,
147	  blockedSet?: Set<string>,
148	  isStrictSanitization = false,
149	): boolean {
150	  key = key.toUpperCase();
151	  value = value?.toUpperCase();
152	
153	  if (key.startsWith('GEMINI_CLI_')) {
154	    return false;
155	  }
156	
157	  if (value) {
158	    for (const pattern of NEVER_ALLOWED_VALUE_PATTERNS) {
159	      if (pattern.test(value)) {
160	        return true;
161	      }
162	    }
163	  }
164	
165	  if (allowedSet?.has(key)) {
166	    return false;
167	  }
168	  if (blockedSet?.has(key)) {
169	    return true;
170	  }
171	
172	  if (ALWAYS_ALLOWED_ENVIRONMENT_VARIABLES.has(key)) {
173	    return false;
174	  }
175	
176	  if (NEVER_ALLOWED_ENVIRONMENT_VARIABLES.has(key)) {
177	    return true;
178	  }
179	
180	  if (isStrictSanitization) {
181	    return true;
182	  }
183	
184	  for (const pattern of NEVER_ALLOWED_NAME_PATTERNS) {
185	    if (pattern.test(key)) {
186	      return true;
187	    }
188	  }
189	
190	  return false;
191	}
