154	+  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
155	+    const sanitizationConfig = getSecureSanitizationConfig(
156	+      req.config?.sanitizationConfig,
157	+      this.options.sanitizationConfig,
158	+    );
